/* 200天照片种子：写入 IndexedDB(christmas-tree / gallery) 后自动刷新一次 */
(function () {
  var IMGS = ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
  try { localStorage.removeItem('ct_removed_defaults'); } catch (e) {}
  if (sessionStorage.getItem('ct_seeded') === '1') return;
  function open() {
    return new Promise(function (res, rej) {
      var r = indexedDB.open('christmas-tree', 1);
      r.onupgradeneeded = function () {
        if (!r.result.objectStoreNames.contains('gallery')) r.result.createObjectStore('gallery', { keyPath: 'id' });
      };
      r.onsuccess = function () { res(r.result); };
      r.onerror = function () { rej(r.error); };
    });
  }
  function count(db) {
    return new Promise(function (res) {
      var t = db.transaction('gallery', 'readonly').objectStore('gallery').count();
      t.onsuccess = function () { res(t.result); };
      t.onerror = function () { res(0); };
    });
  }
  function putAll(db, recs) {
    return new Promise(function (res) {
      var tx = db.transaction('gallery', 'readwrite'), st = tx.objectStore('gallery');
      st.clear();
      recs.forEach(function (r) { st.put(r); });
      tx.oncomplete = function () { res(); };
      tx.onerror = function () { res(); };
    });
  }
  open().then(function (db) {
    return count(db).then(function (n) {
      if (n >= 5) { db.close(); sessionStorage.setItem('ct_seeded', '1'); return; }
      return Promise.all(IMGS.map(function (u, i) {
        return fetch(u).then(function (r) { return r.blob(); }).then(function (b) {
          return { id: 'seed-' + i, name: 'photo-' + (i + 1) + '.jpg', blob: b };
        });
      })).then(function (recs) { return putAll(db, recs); }).then(function () {
        db.close();
        sessionStorage.setItem('ct_seeded', '1');
        location.reload();
      });
    });
  }).catch(function () {});
})();
